import{_ as a,o as e,c as i,a3 as n}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"试用手册：一个账号，你的所有设备","description":"","frontmatter":{},"headers":[],"relativePath":"zh/trial.md","filePath":"zh/trial.md"}'),t={name:"zh/trial.md"};function p(o,s,l,d,h,c){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="试用手册-一个账号-你的所有设备" tabindex="-1">试用手册：一个账号，你的所有设备 <a class="header-anchor" href="#试用手册-一个账号-你的所有设备" aria-label="Permalink to &quot;试用手册：一个账号，你的所有设备&quot;">​</a></h1><p>把私下试用从头到尾跑起来需要什么——中继、手机、电脑、网页——从一台干净的 VPS 到「手机让 Mac 编译项目」。这里写的一切都在私有仓库 <code>nanomuse-trial</code>（分支 <code>trial</code>）里， 直到它进入公开仓库为止。</p><h2 id="_0-what-you-need" tabindex="-1">0. 你需要什么 <a class="header-anchor" href="#_0-what-you-need" aria-label="Permalink to &quot;0. 你需要什么 {#_0-what-you-need}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>用来</th></tr></thead><tbody><tr><td>一台装了 Docker 的小 Linux VPS（1 vCPU / 1 GB 就够）和一个指向它的域名，比如 <code>cloud.example.com</code></td><td>中继 + hub + 网页控制台</td></tr><tr><td>一把 OpenAI 兼容的模型 key——默认是阿里云百炼（Model Studio）；同一把 key 也负责画图</td><td>各台设备上的 Muse 用它思考</td></tr><tr><td>一个发验证码的途径：SMTP 凭据（邮箱登录）和/或阿里云短信（中国大陆手机号）——或者 <code>CODE_SENDER=log</code>，趁着只有你自己在用，从服务器日志里读验证码</td><td>登录</td></tr><tr><td>Android 手机：<code>./gradlew :app:assembleDebug</code> 打出来的 arm64 调试 APK（手动安装）</td><td>手机上的 Muse</td></tr><tr><td>电脑：各自的安装包来自 <code>desktop</code> 工作流的产物——<em>Actions → desktop → Run workflow</em> 一次构建全部四个（Windows <code>-setup.exe</code>、macOS <code>.pkg</code> 的 Apple 芯片版和 Intel 版、Linux <code>.deb</code>）；打一个 <code>desktop-v*</code> 标签也会把它们发布成一个版本</td><td>电脑上的 Muse</td></tr><tr><td>iPhone（可选）：通过 <code>ios-testflight</code> 工作流上 TestFlight——需要 Apple Developer 账号和放在仓库 secrets 里的 App Store Connect API key；先跑 <em>iOS · build check</em>，它这两样都不需要</td><td>hub 上的 iPhone（它能响应 <code>info</code>、<code>open</code>、<code>notify</code>；iPhone 上的 shell、文件和任务还没做）</td></tr></tbody></table><h2 id="_1-the-relay" tabindex="-1">1. 中继 <a class="header-anchor" href="#_1-the-relay" aria-label="Permalink to &quot;1. 中继 {#_1-the-relay}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:nano-muse/nanomuse-trial.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanomuse-trial/cloud</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>填写 <code>.env</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLOUD_DOMAIN=cloud.example.com</span></span>
<span class="line"><span>PUBLIC_BASE=https://cloud.example.com</span></span>
<span class="line"><span>CLOUD_SECRET=&lt;openssl rand -hex 32&gt;        # back it up with data/: rotating it orphans accounts</span></span>
<span class="line"><span>CLOUD_ADMIN_TOKEN=&lt;openssl rand -hex 32&gt;</span></span>
<span class="line"><span>UPSTREAM_BASE=…/compatible-mode/v1          # your Model Studio endpoint</span></span>
<span class="line"><span>UPSTREAM_KEY=sk-…</span></span>
<span class="line"><span>DASHSCOPE_BASE=…/api/v1</span></span>
<span class="line"><span>SIGNUP_OPEN=0                               # members only while you try it; 1 opens sign-up</span></span>
<span class="line"><span>ALLOWED_IDENTIFIERS=139xxxxxxxx, you@example.com   # members: no daily cap</span></span>
<span class="line"><span>DAILY_CAP_CNY=25                            # yuan a day for everyone else once sign-up is open</span></span>
<span class="line"><span>CODE_SENDER=smtp                            # or aliyun / both / log</span></span>
<span class="line"><span>SMTP_HOST=… SMTP_PORT=465 SMTP_USER=… SMTP_PASSWORD=… SMTP_FROM=nanoMuse &lt;no-reply@example.com&gt;</span></span>
<span class="line"><span>HUB_ENABLED=true</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # relay on :8787 behind Caddy, which fetches the certificate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> relay</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # codes appear here when CODE_SENDER=log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/healthz</span></span></code></pre></div><p>网页控制台在 <code>https://cloud.example.com/app/</code>，运营者的页面在 <code>/app/admin/</code> （需要 <code>CLOUD_ADMIN_TOKEN</code>：谁登录了、用量、设备、发放额度 / 停用 / 删除）。 数据（SQLite）放在 <code>cloud/data/</code>；连同 <code>CLOUD_SECRET</code> 一起备份。token 数默认 没有上限；真正限制一个账号的是每日金额上限（<code>DAILY_CAP_CNY</code>），成员不受它约束。</p><p>生产环境的中继 <code>https://cloud.nanomuse.cn</code> 就是这份代码，跑在给 nanomuse.cn 提供 服务的那台机器上，在展示站的 Caddy 后面； <a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/deploy/nanomuse-hk/README.md" target="_blank" rel="noreferrer"><code>cloud/deploy/nanomuse-hk/</code></a> 里有 compose 文件、Caddy 站点配置、备份定时器和部署脚本。</p><h2 id="_2-the-phone" tabindex="-1">2. 手机 <a class="header-anchor" href="#_2-the-phone" aria-label="Permalink to &quot;2. 手机 {#_2-the-phone}&quot;">​</a></h2><p>安装 APK。在第一屏上，「接入模型」→ 你的手机号或邮箱地址 → 验证码 → 完成： nanoMuse Cloud 服务商、一个默认模型组和 hub 连接一次设好。（调试版会显示 「中转服务器」一栏；把你中继的地址填在那里。正式版用默认的中继。）</p><p>「设置 → nanoMuse Cloud」现在多了一个<strong>设备</strong>区：两个开关（可被找到 · 可被操作）、 手机的名字（改成一个你会念出口的——「pixel」「小米」）、其他设备，以及控制台的链接。 手机在 hub 上时，会一直有一条安静的通知。</p><h2 id="_3-the-computers" tabindex="-1">3. 电脑 <a class="header-anchor" href="#_3-the-computers" aria-label="Permalink to &quot;3. 电脑 {#_3-the-computers}&quot;">​</a></h2><p>安装软件包。然后在终端里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nanomuse-desktop</span></span></code></pre></div><p>服务器 → 手机号或邮箱地址 → 验证码。给电脑起个名字（<code>nanomuse-desktop rename mac</code>）。 <code>nanomuse-desktop run --open</code> 在终端里聊天并打开控制台； <code>nanomuse-desktop serve</code> 不开聊天，只让它保持可被联系（想让它一直在线， 就放进登录项 / systemd 用户服务 / 任务计划程序）。</p><h2 id="_4-try-it" tabindex="-1">4. 试一试 <a class="header-anchor" href="#_4-try-it" aria-label="Permalink to &quot;4. 试一试 {#_4-try-it}&quot;">​</a></h2><p>在手机上：「在 mac 上列一下下载文件夹」 「让 desk 把 ~/proj 编译一遍，把最后二十行日志发我」 「电脑截个图给我看」 「给电脑发个通知：该睡了」</p><p>在电脑上：「在手机上截个图」「让 pixel 的 Muse 把最后一条通知读给我」 「给 pixel 发个通知：构建完成」。</p><p>在控制台里：选一台设备，打字；审批以卡片的形式出现。</p><p>凡是删除、发送、付款或者动系统的事都会先问——在你打字的那台设备上问。 远端 Muse 的审批问题也同样回到你手里。</p><h2 id="_5-operating" tabindex="-1">5. 运维 <a class="header-anchor" href="#_5-operating" aria-label="Permalink to &quot;5. 运维 {#_5-operating}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># accounts (hints only, never identifiers) and allowance</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Admin-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLOUD_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/v1/admin/accounts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># top up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Admin-Token: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLOUD_ADMIN_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/v1/admin/grant</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;content-type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;identifier&quot;:&quot;139…&quot;,&quot;tokens&quot;:1000000}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># who is on the hub (with a device&#39;s own key)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer nm_…&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://cloud.example.com/v1/devices</span></span></code></pre></div><p>放别人进来：<code>SIGNUP_OPEN=1</code>，再跑一次 <code>docker compose up -d</code>，任何人都能注册， 受每日上限约束；在管理页上点「设为成员」，或者在 <code>ALLOWED_IDENTIFIERS</code> 里加一行， 就为某一个人解除上限。</p><h2 id="_6-where-it-stands" tabindex="-1">6. 现状 <a class="header-anchor" href="#_6-where-it-stands" aria-label="Permalink to &quot;6. 现状 {#_6-where-it-stands}&quot;">​</a></h2><p>在开发机上验证过的：中继 + hub、Linux 桌面版、Android 模拟器和网页控制台在同一个 账号下——手机→电脑（<code>devices</code>、<code>run</code>、<code>ls</code>、<code>notify</code>、<code>task</code>），电脑→手机（<code>info</code>、 <code>notify</code>、<code>task</code>，自然语言的通知 + 委派），网页→手机和网页→电脑（任务、审批卡片）， 重命名和忘记（控制台里也能做）。macOS 和 Windows 的安装包出自 CI（<code>desktop</code> 工作流， 四个目标全绿），没有在真机上跑过。iOS 这边——登录和 hub 客户端——是在没有 Mac 的情况下 写的；<code>ios-check</code> 工作流是编译测试，<code>ios-testflight</code> 工作流负责交付。手机上的 shell 和文件用的是 Linux 沙箱，arm64 手机上有它（模拟器版没有）。</p>`,28)])])}const u=a(t,[["render",p]]);export{k as __pageData,u as default};
